CREATE TABLE stream_scores (
  livestream_id BIGINT PRIMARY KEY,
  score BIGINT NOT NULL DEFAULT 0,
  KEY score_rank (score, livestream_id)
) ENGINE=InnoDB;

CREATE TABLE user_scores (
  user_id BIGINT PRIMARY KEY,
  name VARBINARY(1024) NOT NULL,
  score BIGINT NOT NULL DEFAULT 0,
  KEY score_rank (score, name)
) ENGINE=InnoDB;

INSERT INTO stream_scores SELECT id, 0 FROM livestreams;
INSERT INTO user_scores SELECT id, name, 0 FROM users;
UPDATE stream_scores s JOIN (
  SELECT livestream_id, SUM(delta) AS score FROM (
    SELECT livestream_id, SUM(tip) AS delta FROM livecomments GROUP BY livestream_id
    UNION ALL
    SELECT livestream_id, COUNT(*) FROM reactions GROUP BY livestream_id
  ) d GROUP BY livestream_id
) t ON t.livestream_id = s.livestream_id SET s.score = t.score;
UPDATE user_scores s JOIN (
  SELECT l.user_id, SUM(r.score) AS score FROM livestreams l
  JOIN stream_scores r ON r.livestream_id = l.id GROUP BY l.user_id
) t ON t.user_id = s.user_id SET s.score = t.score;

CREATE TRIGGER score_new_user AFTER INSERT ON users FOR EACH ROW
  INSERT INTO user_scores (user_id, name) VALUES (NEW.id, NEW.name);
CREATE TRIGGER score_new_stream AFTER INSERT ON livestreams FOR EACH ROW
  INSERT INTO stream_scores (livestream_id) VALUES (NEW.id);

DELIMITER //
CREATE PROCEDURE apply_score(IN stream_id BIGINT, IN delta BIGINT)
BEGIN
  IF delta <> 0 THEN
    UPDATE stream_scores SET score = score + delta WHERE livestream_id = stream_id;
    UPDATE user_scores s JOIN livestreams l ON l.user_id = s.user_id
    SET s.score = s.score + delta WHERE l.id = stream_id;
  END IF;
END//
DELIMITER ;

CREATE TRIGGER score_comment AFTER INSERT ON livecomments FOR EACH ROW
  CALL apply_score(NEW.livestream_id, NEW.tip);
CREATE TRIGGER score_delete_comment AFTER DELETE ON livecomments FOR EACH ROW
  CALL apply_score(OLD.livestream_id, -OLD.tip);
CREATE TRIGGER score_reaction AFTER INSERT ON reactions FOR EACH ROW
  CALL apply_score(NEW.livestream_id, 1);
EOF
