package main

import (
	"context"
	"database/sql"

	"github.com/jmoiron/sqlx"
	"github.com/labstack/echo/v4"
)

type responseDataKey struct{}

type responseData struct {
	users   map[int64]User
	streams map[int64]Livestream
}

func withResponseData(next echo.HandlerFunc) echo.HandlerFunc {
	return func(c echo.Context) error {
		req := c.Request()
		c.SetRequest(req.WithContext(context.WithValue(req.Context(), responseDataKey{}, &responseData{})))
		return next(c)
	}
}

func userResponseByID(ctx context.Context, tx *sqlx.Tx, id int64) (User, error) {
	data, _ := ctx.Value(responseDataKey{}).(*responseData)
	if data != nil {
		if user, ok := data.users[id]; ok {
			return user, nil
		}
	}
	var row struct {
		ID          int64
		Name        string
		DisplayName string `db:"display_name"`
		Description string
		ThemeID     int64          `db:"theme_id"`
		DarkMode    bool           `db:"dark_mode"`
		IconHash    sql.NullString `db:"image_hash"`
	}
	err := tx.GetContext(ctx, &row, `SELECT u.id, u.name, u.display_name, u.description, t.id AS theme_id, t.dark_mode, i.image_hash
		FROM users u JOIN themes t ON t.user_id = u.id LEFT JOIN icons i ON i.user_id = u.id
		WHERE u.id = ? ORDER BY t.id, i.id LIMIT 1`, id)
	if err != nil {
		return User{}, err
	}
	user := User{
		ID: row.ID, Name: row.Name, DisplayName: row.DisplayName, Description: row.Description,
		Theme:    Theme{ID: row.ThemeID, DarkMode: row.DarkMode},
		IconHash: defaultIconHash,
	}
	if row.IconHash.Valid {
		user.IconHash = row.IconHash.String
	}
	if data != nil {
		if data.users == nil {
			data.users = make(map[int64]User)
		}
		data.users[id] = user
	}
	return user, nil
}

func livestreamResponseByID(ctx context.Context, tx *sqlx.Tx, id int64) (Livestream, error) {
	data, _ := ctx.Value(responseDataKey{}).(*responseData)
	if data != nil {
		if stream, ok := data.streams[id]; ok {
			return stream, nil
		}
	}
	var stream LivestreamModel
	if err := tx.GetContext(ctx, &stream, "SELECT * FROM livestreams WHERE id = ?", id); err != nil {
		return Livestream{}, err
	}
	return fillLivestreamResponse(ctx, tx, stream)
}
func getLivecommentsHandler(c echo.Context) error {
	ctx := c.Request().Context()

	if err := verifyUserSession(c); err != nil {
		// echo.NewHTTPErrorが返っているのでそのまま出力
		return err
	}

	livestreamID, err := strconv.Atoi(c.Param("livestream_id"))
	if err != nil {
		return echo.NewHTTPError(http.StatusBadRequest, "livestream_id in path must be integer")
	}

	tx, err := dbConn.BeginTxx(ctx, nil)
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to begin transaction: "+err.Error())
	}
	defer tx.Rollback()

	query := "SELECT * FROM livecomments WHERE livestream_id = ? ORDER BY created_at DESC"
	if c.QueryParam("limit") != "" {
		limit, err := strconv.Atoi(c.QueryParam("limit"))
		if err != nil {
			return echo.NewHTTPError(http.StatusBadRequest, "limit query parameter must be integer")
		}
		query += fmt.Sprintf(" LIMIT %d", limit)
	}

	livecommentModels := []LivecommentModel{}
	err = tx.SelectContext(ctx, &livecommentModels, query, livestreamID)
	if errors.Is(err, sql.ErrNoRows) {
		return c.JSON(http.StatusOK, []*Livecomment{})
	}
	if err != nil {
		return echo.NewHTTPError(http.StatusInternalServerError, "failed to get livecomments: "+err.Error())
	}

	livecomments := make([]Livecomment, len(livecommentModels))
	for i := range livecommentModels {
