package main

import (
	"context"
	"encoding/binary"
	"fmt"
	"io"
	"log"
	"net"
	"net/netip"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/jmoiron/sqlx"
	"golang.org/x/net/dns/dnsmessage"
)

const (
	dnsZone = "u.isucon.dev."
	dnsBackend = "127.0.0.1:5353"
)

type dnsRecord struct {
	Name string
	Type string
	Content string
	TTL uint32
}

type dnsFrontend struct {
	db *sqlx.DB
	mu sync.RWMutex
	addresses map[string][]dnsmessage.Resource
	existing map[string]bool
	soa dnsmessage.Resource
}

var authoritativeDNS *dnsFrontend

const dnsRecordsQuery = `SELECT r.name, r.type, r.content, r.ttl
	FROM records r JOIN domains d ON d.id = r.domain_id
	WHERE d.name = 'u.isucon.dev' AND r.disabled = 0 AND r.auth = 1`

func dnsRecordName(name string) string {
	return strings.ToLower(strings.TrimSuffix(name, ".")) + "."
}

func (r dnsRecord) resource() (dnsmessage.Resource, error) {
	name, err := dnsmessage.NewName(dnsRecordName(r.Name))
	if err != nil {
		return dnsmessage.Resource{}, err
	}
	header := dnsmessage.ResourceHeader{Name: name, Class: dnsmessage.ClassINET, TTL: r.TTL}
	switch r.Type {
	case "A":
		address, err := netip.ParseAddr(r.Content)
		if err != nil || !address.Is4() {
			return dnsmessage.Resource{}, fmt.Errorf("invalid A record for %q", r.Name)
		}
		return dnsmessage.Resource{Header: header, Body: &dnsmessage.AResource{A: address.As4()}}, nil
	case "SOA":
		fields := strings.Fields(r.Content)
		if len(fields) != 7 {
			return dnsmessage.Resource{}, fmt.Errorf("invalid SOA record for %q", r.Name)
		}
		primary, err := dnsmessage.NewName(dnsRecordName(fields[0]))
		if err != nil {
			return dnsmessage.Resource{}, err
		}
		mailbox, err := dnsmessage.NewName(dnsRecordName(fields[1]))
		if err != nil {
			return dnsmessage.Resource{}, err
		}
		var values [5]uint32
		for i := range values {
			value, err := strconv.ParseUint(fields[i+2], 10, 32)
			if err != nil {
				return dnsmessage.Resource{}, err
			}
			values[i] = uint32(value)
		}
		return dnsmessage.Resource{Header: header, Body: &dnsmessage.SOAResource{
			NS: primary, MBox: mailbox, Serial: values[0], Refresh: values[1], Retry: values[2],
			Expire: values[3], MinTTL: values[4],
		}}, nil
	default:
		return dnsmessage.Resource{}, fmt.Errorf("unsupported DNS snapshot record type %q", r.Type)
	}
}

func (s *dnsFrontend) reload(ctx context.Context) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	var records []dnsRecord
	if err := s.db.SelectContext(ctx, &records, dnsRecordsQuery); err != nil {
		return err
	}
	addresses := make(map[string][]dnsmessage.Resource)
	existing := make(map[string]bool)
	var soa dnsmessage.Resource
	for _, record := range records {
		name := dnsRecordName(record.Name)
		for parent := name; strings.HasSuffix(parent, dnsZone); {
			existing[parent] = true
			if parent == dnsZone {
				break
			}
			_, parent, _ = strings.Cut(parent, ".")
		}
		if record.Type != "A" && record.Type != "SOA" {
			continue
		}
		resource, err := record.resource()
		if err != nil {
			return err
		}
		if record.Type == "A" {
			addresses[name] = append(addresses[name], resource)
		} else if name == dnsZone {
			soa = resource
		}
	}
	if soa.Body == nil {
		return fmt.Errorf("missing SOA record for %s", dnsZone)
	}
	s.addresses = addresses
	s.existing = existing
	s.soa = soa
	return nil
}

func (s *dnsFrontend) addHost(ctx context.Context, username string) error {
	name := dnsRecordName(username + "." + dnsZone)
	var records []dnsRecord
	if err := s.db.SelectContext(ctx, &records, dnsRecordsQuery+" AND r.name = ? AND r.type = 'A'", strings.TrimSuffix(name, ".")); err != nil {
		return err
	}
	if len(records) == 0 {
		return fmt.Errorf("DNS record for %q was not found after registration", username)
	}
	addresses := make([]dnsmessage.Resource, 0, len(records))
	for _, record := range records {
		resource, err := record.resource()
		if err != nil {
			return err
		}
		addresses = append(addresses, resource)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	s.addresses[name] = addresses
	for parent := name; strings.HasSuffix(parent, "."+dnsZone); {
		s.existing[parent] = true
		_, parent, _ = strings.Cut(parent, ".")
	}
	return nil
}

func (s *dnsFrontend) answer(packet []byte) ([]byte, bool) {
	var request dnsmessage.Message
	if err := request.Unpack(packet); err != nil || request.Response || request.OpCode != 0 || len(request.Questions) != 1 {
		return nil, false
	}
	question := request.Questions[0]
	name := strings.ToLower(question.Name.String())
	if name != dnsZone && !strings.HasSuffix(name, "."+dnsZone) {
		return nil, false
	}
	if question.Class != dnsmessage.ClassINET || question.Type != dnsmessage.TypeA {
		return nil, false
	}

	s.mu.RLock()
	addresses, exists, soa := s.addresses[name], s.existing[name], s.soa
	s.mu.RUnlock()
	reply := dnsmessage.Message{
		Header: dnsmessage.Header{ID: request.ID, Response: true, Authoritative: true, RecursionDesired: request.RecursionDesired},
		Questions: request.Questions,
		Answers: addresses,
	}
	if len(addresses) == 0 {
		reply.Authorities = []dnsmessage.Resource{soa}
		if !exists {
			reply.RCode = dnsmessage.RCodeNameError
		}
	}
	out, err := reply.Pack()
	return out, err == nil
}

type forwardedDNSPacket struct {
	data []byte
	client net.Addr
}

func (s *dnsFrontend) serveUDP(listener net.PacketConn) {
	forward := make(chan forwardedDNSPacket, 128)
	for i := 0; i < 4; i++ {
		go func() {
			for packet := range forward {
				conn, err := net.DialTimeout("udp", dnsBackend, time.Second)
				if err != nil {
					continue
				}
				_ = conn.SetDeadline(time.Now().Add(time.Second))
				reply := make([]byte, 4096)
				if _, err := conn.Write(packet.data); err == nil {
					if n, err := conn.Read(reply); err == nil {
						_, _ = listener.WriteTo(reply[:n], packet.client)
					}
				}
				_ = conn.Close()
			}
		}()
	}
	defer close(forward)
	var packet [4096]byte
	for {
		size, client, err := listener.ReadFrom(packet[:])
		if err != nil {
			log.Printf("DNS UDP listener: %v", err)
			return
		}
		if reply, ok := s.answer(packet[:size]); ok {
			_, _ = listener.WriteTo(reply, client)
			continue
		}
		select {
		case forward <- forwardedDNSPacket{data: append([]byte(nil), packet[:size]...), client: client}:
		default:
		}
	}
}

func (s *dnsFrontend) serveTCP(listener net.Listener) {
	inflight := make(chan struct{}, 128)
	for {
		client, err := listener.Accept()
		if err != nil {
			log.Printf("DNS TCP listener: %v", err)
			return
		}
		select {
		case inflight <- struct{}{}:
			go func() {
				defer func() { <-inflight }()
				defer client.Close()
				for {
					_ = client.SetDeadline(time.Now().Add(5 * time.Second))
					if err := s.handleTCPQuery(client); err != nil {
						return
					}
				}
			}()
		default:
			_ = client.Close()
		}
	}
}

func (s *dnsFrontend) handleTCPQuery(client net.Conn) error {
	var length [2]byte
	if _, err := io.ReadFull(client, length[:]); err != nil {
		return err
	}
	packet := make([]byte, binary.BigEndian.Uint16(length[:]))
	if _, err := io.ReadFull(client, packet); err != nil {
		return err
	}
	reply, ok := s.answer(packet)
	if !ok {
		upstream, err := net.DialTimeout("tcp", dnsBackend, time.Second)
		if err != nil {
			return err
		}
		defer upstream.Close()
		_ = upstream.SetDeadline(time.Now().Add(time.Second))
		if _, err := upstream.Write(append(length[:], packet...)); err != nil {
			return err
		}
		if _, err := io.ReadFull(upstream, length[:]); err != nil {
			return err
		}
		reply = make([]byte, binary.BigEndian.Uint16(length[:]))
		if _, err := io.ReadFull(upstream, reply); err != nil {
			return err
		}
	}
	binary.BigEndian.PutUint16(length[:], uint16(len(reply)))
	_, err := client.Write(append(length[:], reply...))
	return err
}

func startDNSFrontend(addr, dsn string) (*dnsFrontend, error) {
	db, err := sqlx.Open("mysql", dsn)
	if err != nil {
		return nil, err
	}
	db.SetMaxOpenConns(4)
	db.SetMaxIdleConns(4)

	server := &dnsFrontend{db: db}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := server.reload(ctx); err != nil {
		_ = db.Close()
		return nil, err
	}

	udp, err := net.ListenPacket("udp", addr)
	if err != nil {
		_ = db.Close()
		return nil, err
	}
	tcp, err := net.Listen("tcp", addr)
	if err != nil {
		_ = udp.Close()
		_ = db.Close()
		return nil, err
	}
	go server.serveUDP(udp)
	go server.serveTCP(tcp)
	return server, nil
}
