cat > go/read_model.go <<'EOF'
package main

import (
	"context"
	"crypto/subtle"
	"fmt"
	"net/http"
	"os"
	"sync"
	"sync/atomic"
	"time"

	"github.com/labstack/echo/v4"
)

type cachedUser struct {
	user User
	iconID int64
}

type cachedIcon struct {
	id int64
	hash string
	image []byte
	complete bool
}

type readModel struct {
	users sync.Map
	icons sync.Map
	streams sync.Map
	tags sync.Map
}

var liveReadModel atomic.Pointer[readModel]
var internalClient = &http.Client{Timeout: 5 * time.Second}

func keepNewerIcon(model *readModel, username string, next *cachedIcon) {
	for {
		raw, loaded := model.icons.LoadOrStore(username, next)
		if !loaded {
			return
		}
		old := raw.(*cachedIcon)
		if old.id > next.id || (old.id == next.id && old.complete && !next.complete) {
			return
		}
		if model.icons.CompareAndSwap(username, old, next) {
			return
		}
	}
}

func (m *readModel) updateUserIcon(id int64, username string, next *cachedIcon) {
	keepNewerIcon(m, username, next)
	for {
		raw, ok := m.users.Load(id)
		if !ok {
			return
		}
		old := raw.(cachedUser)
		if old.iconID >= next.id {
			return
		}
		updated := old
		updated.user.IconHash = next.hash
		updated.iconID = next.id
		if m.users.CompareAndSwap(id, old, updated) {
			return
		}
	}
}

func (m *readModel) rememberUser(row userResponseRow) User {
	next := cachedUser{user: row.user(), iconID: row.IconID}
	stored, _ := m.users.LoadOrStore(row.ID, next)
	keepNewerIcon(m, row.Name, &cachedIcon{
		id: row.IconID, hash: next.user.IconHash, complete: row.IconID == 0,
	})
	if raw, ok := m.icons.Load(row.Name); ok {
		icon := raw.(*cachedIcon)
		if icon.id > stored.(cachedUser).iconID {
			m.updateUserIcon(row.ID, row.Name, icon)
		}
	}
	current, _ := m.users.Load(row.ID)
	return current.(cachedUser).user
}

func resetRemoteReadModel(ctx context.Context) error {
	url := os.Getenv("ISUPIPE_READ_MODEL_RESET_URL")
	if url == "" {
		return nil
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, url, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+os.Getenv("ISUPIPE_READ_MODEL_SECRET"))
	resp, err := internalClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusNoContent {
		return fmt.Errorf("read model reset returned %d", resp.StatusCode)
	}
	return nil
}

func configureReadModel(e *echo.Echo) {
	secret := os.Getenv("ISUPIPE_READ_MODEL_SECRET")
	if secret == "" || os.Getenv("ISUPIPE_READ_MODEL_CACHE") != "1" {
		return
	}
	liveReadModel.Store(&readModel{})
	e.POST("/internal/clear-read-model", func(c echo.Context) error {
		want := "Bearer " + secret
		if subtle.ConstantTimeCompare([]byte(c.Request().Header.Get("Authorization")), []byte(want)) != 1 {
			return c.NoContent(http.StatusUnauthorized)
		}
		liveReadModel.Store(&readModel{})
		return c.NoContent(http.StatusNoContent)
	})
}
EOF
