cat > go/recent_timeline.go <<'EOF'
package main

import (
	"context"
	"sort"
	"sync"
)

const recentTimelineSize = 32

type streamFeed struct {
	comments recentTimeline[LivecommentModel]
	reactions recentTimeline[ReactionModel]
}

type recentTimeline[T any] struct {
	mu sync.Mutex
	revision uint64
	rows []T
}

func (m *readModel) feed(streamID int64) *streamFeed {
	if feed, ok := m.feeds.Load(streamID); ok {
		return feed.(*streamFeed)
	}
	feed, _ := m.feeds.LoadOrStore(streamID, &streamFeed{})
	return feed.(*streamFeed)
}

func requestReadModel(ctx context.Context) *readModel {
	if data, _ := ctx.Value(responseDataKey{}).(*responseData); data != nil {
		return data.model
	}
	return nil
}

func (t *recentTimeline[T]) snapshot(ctx context.Context, query string, streamID int64, limit int) ([]T, error) {
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.rows == nil {
		rows := make([]T, 0)
		if err := dbConn.SelectContext(ctx, &rows, query+" LIMIT ?", streamID, recentTimelineSize); err != nil {
			return nil, err
		}
		t.rows = rows
	}
	return t.rows[:min(limit, len(t.rows))], nil
}

func (t *recentTimeline[T]) version() uint64 {
	t.mu.Lock()
	defer t.mu.Unlock()
	return t.revision
}

func (t *recentTimeline[T]) invalidate() {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.rows = nil
	t.revision++
}

func (t *recentTimeline[T]) insert(event T, id, createdAt int64, revision uint64, metadata func(T) (int64, int64)) {
	t.mu.Lock()
	defer t.mu.Unlock()
	if revision != t.revision {
		t.rows = nil
		return
	}
	if t.rows == nil {
		return
	}
	index := sort.Search(len(t.rows), func(i int) bool {
		rowID, rowTime := metadata(t.rows[i])
		return rowTime < createdAt || (rowTime == createdAt && rowID <= id)
	})
	if index >= recentTimelineSize {
		return
	}
	if index < len(t.rows) {
		rowID, _ := metadata(t.rows[index])
		if rowID == id {
			return
		}
	}
	next := make([]T, min(len(t.rows)+1, recentTimelineSize))
	copy(next, t.rows[:index])
	next[index] = event
	copy(next[index+1:], t.rows[index:])
	t.rows = next
}

func commentMetadata(row LivecommentModel) (int64, int64) {
	return row.ID, row.CreatedAt
}

func reactionMetadata(row ReactionModel) (int64, int64) {
	return row.ID, row.CreatedAt
}
EOF
