			case forward <- forwardedDNSPacket{data: append([]byte(nil), packet...), client: message.Addr}:
			default:
			}
		}
		for pending := output[:sent]; len(pending) > 0; {
			written, err := batch.WriteBatch(pending, 0)
			if err != nil || written == 0 {
				break
			}
			pending = pending[written:]
