				c.Response().Header().Set(echo.HeaderContentEncoding, "gzip")
				body = p.compressed
			}
		}
	}
	return c.JSONBlob(http.StatusOK, body)
}

func acceptsGzip(values []string) bool {
	var wildcard, gzipAllowed, gzipSeen bool
	for _, value := range values {
		for _, item := range strings.Split(value, ",") {
			coding, params, _ := strings.Cut(item, ";")
			coding = strings.ToLower(strings.TrimSpace(coding))
			if coding != "gzip" && coding != "*" {
				continue
			}
			accepted := true
			for _, param := range strings.Split(params, ";") {
				name, weight, ok := strings.Cut(param, "=")
				if ok && strings.EqualFold(strings.TrimSpace(name), "q") {
					factor, err := strconv.ParseFloat(strings.TrimSpace(weight), 64)
					accepted = err == nil && factor > 0 && factor <= 1
					break
				}
			}
			if coding == "gzip" {
				gzipSeen = true
				gzipAllowed = gzipAllowed || accepted
			} else {
				wildcard = wildcard || accepted
			}
		}
	}
	if gzipSeen {
		return gzipAllowed
	}
	return wildcard
}
