DELIMITER //
CREATE PROCEDURE reserve_stream(
  IN actor_id BIGINT,
  IN stream_title MEDIUMTEXT CHARACTER SET utf8mb4,
  IN stream_description MEDIUMTEXT CHARACTER SET utf8mb4,
  IN stream_playlist MEDIUMTEXT CHARACTER SET utf8mb4,
  IN stream_thumbnail MEDIUMTEXT CHARACTER SET utf8mb4,
  IN stream_start BIGINT,
  IN stream_end BIGINT,
  IN stream_tags JSON
)
BEGIN
  DECLARE minimum_slots BIGINT DEFAULT NULL;
  DECLARE unavailable_start BIGINT DEFAULT 0;
  DECLARE unavailable_end BIGINT DEFAULT 0;
  DECLARE result_id BIGINT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT MIN(slot) INTO minimum_slots FROM reservation_slots
    WHERE start_at BETWEEN stream_start AND stream_end AND end_at <= stream_end
    FOR UPDATE;
  IF minimum_slots < 1 THEN
    SELECT start_at, end_at INTO unavailable_start, unavailable_end FROM reservation_slots
      WHERE start_at BETWEEN stream_start AND stream_end AND end_at <= stream_end AND slot < 1
      ORDER BY start_at, id LIMIT 1;
    ROLLBACK;
  ELSE
    UPDATE reservation_slots SET slot = slot - 1
      WHERE start_at BETWEEN stream_start AND stream_end AND end_at <= stream_end;
    INSERT INTO livestreams (user_id, title, description, playlist_url, thumbnail_url, start_at, end_at)
      VALUES (actor_id, stream_title, stream_description, stream_playlist, stream_thumbnail, stream_start, stream_end);
    SET result_id = LAST_INSERT_ID();
    INSERT INTO livestream_tags (livestream_id, tag_id)
      SELECT result_id, tag_id FROM JSON_TABLE(stream_tags, '$[*]' COLUMNS(
        ord FOR ORDINALITY, tag_id BIGINT PATH '$' ERROR ON ERROR
      )) AS requested_tags ORDER BY ord;
    COMMIT;
  END IF;
  SELECT result_id AS id, unavailable_start AS slot_start, unavailable_end AS slot_end;
END//
DELIMITER ;
EOF
